arguments.content:
/**
 * records.js — data layer for the Kartenzeit seed collection (owner: zurich-maps-0).
 *
 * One module knows how a record looks. Everything else (map, search, results,
 * detail) asks this module. Isomorphic ES module: it runs in the browser and in
 * Node (tests, scripts) because it only uses `fetch` when a URL loader is used.
 *
 * Data contract: coordination/data-contract.md (schema fixed by coordination
 * decision D4). Public API is documented in docs/DATA.md.
 */

export const DATA_URL = '/data/records.json';
export const SOURCES_URL = '/data/sources.json';
export const OVERLAYS_URL = '/data/overlays.json';

/** Plausibility window for publication years (data contract rule 3). */
export const YEAR_MIN = 1400;
export const YEAR_MAX = 2100;

const has = (value) => value !== undefined && value !== null && value !== '';

/** A record can be dated by what the map depicts, if upstream states it. */
export function dateRange(record) {
  const depictedStart = num(record.depictedYearStart);
  const depictedEnd = num(record.depictedYearEnd);
  if (depictedStart !== null || depictedEnd !== null) {
    const start = depictedStart ?? depictedEnd;
    const end = depictedEnd ?? depictedStart;
    return { start: Math.min(start, end), end: Math.max(start, end), basis: 'depicted' };
  }
  const start = num(record.yearStart);
  const end = num(record.yearEnd) ?? start;
  if (start === null) return { start: null, end: null, basis: 'unknown' };
  return { start, end: end === null ? start : Math.max(start, end), basis: 'publication' };
}

/** Human-readable year label, honest about precision. */
export function formatYear(record) {
  const { start, end, basis } = dateRange(record);
  if (start === null) return 'ohne Jahr';
  const range = start === end ? `${start}` : `${start}–${end}`;
  return basis === 'depicted' ? `um ${range}` : range;
}

export function yearLabel(state) {
  const from = num(state?.from);
  const to = num(state?.to);
  if (from === null && to === null) return 'alle Jahre';
  if (from !== null && to !== null && from === to) return `${from}`;
  return `${from ?? '…'}–${to ?? '…'}`;
}

/** Does the record's own date range overlap [from, to]? */
export function recordOverlapsYears(record, from, to) {
  const { start, end } = dateRange(record);
  if (start === null) return true; // undated items are never hidden by a time filter
  const lo = num(from) ?? YEAR_MIN;
  const hi = num(to) ?? YEAR_MAX;
  return start <= hi && end >= lo;
}

/** Records whose date range contains a single year (used for overlay matching). */
export function recordCoversYear(record, year) {
  const { start, end } = dateRange(record);
  if (start === null) return false;
  return start <= year && end >= year;
}

/**
 * Normalise one upstream-shaped record. Unknown fields are preserved; known
 * fields are coerced so downstream code can rely on them.
 */
export function normalizeRecord(raw = {}) {
  const record = { ...raw };
  record.id = String(raw.id ?? '');
  record.title = String(raw.title ?? '').trim();
  record.type = has(raw.type) ? String(raw.type) : 'map';
  record.providerId = String(raw.providerId ?? '');
  record.institution = String(raw.institution ?? '').trim();
  record.rights = String(raw.rights ?? '').trim();
  record.recordUrl = String(raw.recordUrl ?? '');
  record.thumbnail = has(raw.thumbnail) ? String(raw.thumbnail) : null;
  record.iiifManifest = has(raw.iiifManifest) ? String(raw.iiifManifest) : null;
  record.creators = Array.isArray(raw.creators) ? raw.creators.filter(has).map(String) : [];
  record.yearStart = num(raw.yearStart);
  record.yearEnd = num(raw.yearEnd) ?? num(raw.yearStart);
  record.depictedYearStart = num(raw.depictedYearStart);
  record.depictedYearEnd = num(raw.depictedYearEnd);
  record.geo = isPoint(raw.geo) ? { lat: Number(raw.geo.lat), lon: Number(raw.geo.lon) } : null;
  record.extent = isBounds(raw.extent)
    ? {
        west: Number(raw.extent.west),
        east: Number(raw.extent.east),
        south: Number(raw.extent.south),
        north: Number(raw.extent.north),
      }
    : null;
  record.overlay = raw.overlay && typeof raw.overlay === 'object' ? raw.overlay : null;
  return record;
}

export function isPoint(value) {
  return !!value && Number.isFinite(Number(value.lat)) && Number.isFinite(Number(value.lon));
}

export function isBounds(value) {
  return (
    !!value &&
    ['west', 'east', 'south', 'north'].every((key) => Number.isFinite(Number(value[key]))) &&
    Number(value.west) < Number(value.east) &&
    Number(value.south) < Number(value.north)
  );
}

/** Accepts an array, a bare array of records, or a dataset object. */
export function toRecordList(input) {
  const list = Array.isArray(input) ? input : Array.isArray(input?.records) ? input.records : [];
  return list.map(normalizeRecord).filter((record) => record.id && record.title);
}

/** Load the seed dataset. `fetchImpl` keeps this usable in tests. */
export async function loadDataset({ url = DATA_URL, fetchImpl } = {}) {
  const doFetch = fetchImpl ?? globalThis.fetch;
  if (typeof doFetch !== 'function') throw new Error('no fetch implementation available');
  const res = await doFetch(url, { headers: { accept: 'application/json' } });
  if (!res.ok) throw new Error(`records: HTTP ${res.status} for ${url}`);
  const doc = await res.json();
  return {
    records: toRecordList(doc),
    generatedAt: doc.generatedAt ?? null,
    method: doc.method ?? null,
    skipped: Array.isArray(doc.skipped) ? doc.skipped : [],
  };
}

export async function loadSources({ url = SOURCES_URL, fetchImpl } = {}) {
  const doFetch = fetchImpl ?? globalThis.fetch;
  const res = await doFetch(url, { headers: { accept: 'application/json' } });
  if (!res.ok) throw new Error(`sources: HTTP ${res.status} for ${url}`);
  return res.json();
}

/**
 * Index + aggregate facts for the UI header and the filter panel.
 * Returned shape is stable; see docs/DATA.md.
 */
export function buildIndex(records = []) {
  const byId = new Map();
  const providerCounts = new Map();
  const institutionCounts = new Map();
  let minYear = null;
  let maxYear = null;
  let geolocated = 0;
  for (const record of records) {
    byId.set(record.id, record);
    providerCounts.set(record.providerId, (providerCounts.get(record.providerId) ?? 0) + 1);
    if (record.institution) {
      institutionCounts.set(record.institution, (institutionCounts.get(record.institution) ?? 0) + 1);
    }
    const range = dateRange(record);
    if (range.start !== null) {
      minYear = minYear === null ? range.start : Math.min(minYear, range.start);
      maxYear = maxYear === null ? range.end : Math.max(maxYear, range.end);
    }
    if (record.geo || record.extent) geolocated += 1;
  }
  return {
    records,
    byId,
    providerCounts,
    institutionCounts,
    minYear,
    maxYear,
    geolocated,
    total: records.length,
  };
}

/** Time-axis domain for the range sliders, snapped to a readable decade. */
export function yearDomain(index, fallback = { min: 1500, max: 2025 }) {
  const min = index?.minYear ?? fallback.min;
  const max = index?.maxYear ?? fallback.max;
  const snappedMin = Math.floor(Math.max(YEAR_MIN, Math.min(min, max)) / 5) * 5;
  const snappedMax = Math.ceil(Math.min(YEAR_MAX, Math.max(min, max)) / 5) * 5;
  return { min: snappedMin, max: snappedMax };
}

/** Geometry tests shared by map and list. `bounds` = {west, south, east, north}. */
export function boundsIntersect(a, b) {
  return !!a && !!b && a.west <= b.east && a.east >= b.west && a.south <= b.north && a.north >= b.south;
}

export function pointInBounds(point, bounds) {
  if (!isPoint(point) || !isBounds(bounds)) return false;
  const lat = Number(point.lat);
  const lon = Number(point.lon);
  return lat >= bounds.south && lat <= bounds.north && lon >= bounds.west && lon <= bounds.east;
}

/** Place vs. area: bbox overlap for maps with an extent, point test otherwise. */
export function recordInBounds(record, bounds) {
  if (!isBounds(bounds)) return true;
  if (record.extent) return boundsIntersect(record.extent, bounds);
  if (record.geo) return pointInBounds(record.geo, bounds);
  return false;
}

/** Records that cannot be placed on a map at all (shown when the filter is off). */
export function hasLocation(record) {
  return !!(record.extent || record.geo);
}

export function recordsInBounds(records, bounds) {
  return records.filter((record) => recordInBounds(record, bounds));
}

export function searchRecords(records, text) {
  const needle = String(text ?? '').trim().toLowerCase();
  if (!needle) return records;
  const terms = needle.split(/\s+/).filter(Boolean);
  return records.filter((record) => {
    const haystack = [
      record.title,
      ...(record.titleAlt ?? []),
      ...(record.creators ?? []),
      record.institution,
      record.shelfmark,
      record.imprint,
      record.publisher,
      record.id,
    ]
      .filter(Boolean)
      .join(' \u0001 ')
      .toLowerCase();
    return terms.every((term) => haystack.includes(term));
  });
}

export function providerFilter(state) {
  const value = state?.provider;
  if (!value || value === 'all') return null;
  const list = Array.isArray(value) ? value : String(value).split(',');
  return new Set(list.map((item) => item.trim()).filter(Boolean));
}

/**
 * The single filter pipeline used by the results list *and* the map, so both
 * always agree: text → years → providers → viewport.
 */
export function filterRecords(state = {}, records = [], { bounds = null, viewportOnly = false } = {}) {
  const providers = providerFilter(state);
  let out = records;
  if (state.text) out = searchRecords(out, state.text);
  out = out.filter((record) => recordOverlapsYears(record, state.from, state.to));
  if (providers && providers.size) out = out.filter((record) => providers.has(record.providerId));
  if (viewportOnly && bounds) out = out.filter((record) => recordInBounds(record, bounds));
  return out;
}

export function sortRecords(records, order = 'year-desc') {
  const sorted = [...records];
  const key = (record) => {
    const range = dateRange(record);
    return range.start ?? -Infinity;
  };
  if (order === 'year-asc') sorted.sort((a, b) => key(a) - key(b) || a.title.localeCompare(b.title, 'de'));
  else if (order === 'title') sorted.sort((a, b) => a.title.localeCompare(b.title, 'de'));
  else sorted.sort((a, b) => key(b) - key(a) || a.title.localeCompare(b.title, 'de'));
  return sorted;
}

/** Short label for the holding institution — used in dense list rows. */
export function institutionShort(record) {
  const full = record.institution ?? '';
  if (!full) return record.providerId;
  return full
    .replace(/^Zentralbibliothek Zürich$/, 'ZB Zürich')
    .replace(/^ETH-Bibliothek Zürich$/, 'ETH-Bibliothek')
    .replace(/,.*$/, '');
}

export function providerLabel(providerId, sources = null) {
  const known = sources?.providers?.find((provider) => provider.id === providerId);
  if (known?.name) return known.name.split('–')[0].trim();
  return providerId;
}

/**
 * Static validation used by tests and by `scripts/verify-records.mjs`.
 * Returns every problem instead of throwing, so CI can print a report.
 */
export function validateRecords(doc, sources = null) {
  const errors = [];
  const warnings = [];
  const records = toRecordList(doc);
  if (!records.length) errors.push('dataset contains no usable records');
  const providerIds = new Set((sources?.providers ?? []).map((provider) => provider.id));
  const overlayHosts = new Set((sources?.providers ?? []).flatMap((provider) => provider.apiHosts ?? []));
  const ids = new Set();
  for (const record of records) {
    const where = `record ${record.id || '(no id)'}`;
    if (!record.id) errors.push(`${where}: missing id`);
    if (ids.has(record.id)) errors.push(`${where}: duplicate id`);
    ids.add(record.id);
    if (!/^[a-z0-9-]+:.+$/.test(record.id)) errors.push(`${where}: id is not <providerId>:<upstream id>`);
    if (!record.title) errors.push(`${where}: missing title`);
    if (!record.yearStart || record.yearStart < YEAR_MIN || record.yearStart > YEAR_MAX) {
      errors.push(`${where}: implausible yearStart ${record.yearStart}`);
    }
    if (record.yearEnd && record.yearStart && record.yearEnd < record.yearStart) {
      errors.push(`${where}: yearEnd before yearStart`);
    }
    if (!/^https:\/\//.test(record.recordUrl)) errors.push(`${where}: recordUrl must be https`);
    if (!record.institution) errors.push(`${where}: missing institution`);
    if (!record.rights) errors.push(`${where}: missing rights`);
    if (!record.thumbnail || !/^https:\/\//.test(record.thumbnail)) {
      warnings.push(`${where}: no https thumbnail`);
    }
    if (record.providerId && providerIds.size && !providerIds.has(record.providerId)) {
      errors.push(`${where}: unknown providerId ${record.providerId}`);
    }
    if (record.extent && !isBounds(record.extent)) errors.push(`${where}: invalid extent bbox`);
    if (record.geo && !isPoint(record.geo)) errors.push(`${where}: invalid geo point`);
    if (record.depictedYearStart && !record.yearStart) {
      warnings.push(`${where}: depicted date without publication date`);
    }
    if (record.overlay) {
      const template = String(record.overlay.urlTemplate ?? '');
      if (!/^https:\/\//.test(template)) errors.push(`${where}: overlay.urlTemplate must be https`);
      else if (overlayHosts.size) {
        const host = new URL(template).host;
        if (!overlayHosts.has(host)) errors.push(`${where}: overlay host ${host} is not in the source registry`);
      }
      if (!record.overlay.attribution) warnings.push(`${where}: overlay without attribution`);
    }
  }
  return { ok: errors.length === 0, errors, warnings, count: records.length };
}

/** dom.js — tiny DOM helpers shared by the modules (owner: zurich-maps-1). */

/**
 * Create an element.
 *   el('p', { class: 'lead' }, 'text')
 *   el('a', { class: 'btn', href, target: '_blank' }, 'Original')
 * Attribute values of `null`/`false` are skipped; `on*` keys become listeners.
 */
export function el(tag, props = null, ...children) {
  const node = document.createElement(tag);
  if (props) {
    for (const [key, value] of Object.entries(props)) {
      if (value === null || value === undefined || value === false) continue;
      if (key === 'class' || key === 'className') node.className = value;
      else if (key === 'text') node.textContent = String(value);
      else if (key === 'html') node.innerHTML = value;
      else if (key.startsWith('on') && typeof value === 'function') {
        node.addEventListener(key.slice(2).toLowerCase(), value);
      } else if (key === 'dataset') Object.assign(node.dataset, value);
      else if (value === true) node.setAttribute(key, '');
      else node.setAttribute(key, String(value));
    }
  }
  for (const child of children.flat()) {
    if (child === null || child === undefined || child === false) continue;
    node.append(child instanceof Node ? child : document.createTextNode(String(child)));
  }
  return node;
}

export function clear(node) {
  while (node?.firstChild) node.removeChild(node.firstChild);
  return node;
}

export function $(selector, root = document) {
  return root.querySelector(selector);
}

export function byId(id) {
  return document.getElementById(id);
}

export function setHidden(node, hidden) {
  if (!node) return;
  if (hidden) node.setAttribute('hidden', '');
  else node.removeAttribute('hidden');
}

export function setText(node, text) {
  if (node) node.textContent = text ?? '';
}

/** Announce a short status message to assistive tech (polite by default). */
export function setStatus(node, message) {
  if (!node) return;
  node.textContent = message ?? '';
}

export function debounce(fn, wait = 250) {
  let timer = null;
  const wrapped = (...args) => {
    clearTimeout(timer);
    timer = setTimeout(() => fn(...args), wait);
  };
  wrapped.cancel = () => clearTimeout(timer);
  return wrapped;
}

export function prefersReducedMotion() {
  return globalThis.matchMedia?.('(prefers-reduced-motion: reduce)').matches ?? false;
}

/** Escape text for use inside an attribute or a small HTML fragment. */
export function escapeHtml(value) {
  return String(value ?? '').replace(/[&<>"']/g, (char) => ({
    '&': '&amp;',
    '<': '&lt;',
    '>': '&gt;',
    '"': '&quot;',
    "'": '&#39;',
  })[char]);
}

/** Tooltips/labels: "Zentralbibliothek Zürich · Public Domain Mark 1.0" */
export function joinMeta(parts, separator = ' · ') {
  return parts.filter(Boolean).join(separator);
}

/**
 * store.js — URL-backed application state + event bus (owner: zurich-maps-1).
 *
 * Every user-visible selection is in the URL, so searches and opened maps are
 * shareable and survive reloads. `replaceState` keeps the history clean while
 * the user drags sliders or pans the map; `popstate` restores earlier URLs.
 */

/** Zürich as initial view — the canton is the design reference and the seed. */
export const ZURICH = { lat: 47.3769, lon: 8.5417, zoom: 13 };

const PARAM_MAP = {
  q: 'place',
  lat: 'lat',
  lon: 'lon',
  zoom: 'z',
  from: 'from',
  to: 'to',
  provider: 'p',
  text: 't',
  selected: 'sel',
  viewportOnly: 'vp',
  overlay: 'ov',
  overlayTime: 'ovt',
};

function defaults() {
  return {
    place: '',
    lat: ZURICH.lat,
    lon: ZURICH.lon,
    zoom: ZURICH.zoom,
    from: null,
    to: null,
    provider: 'all',
    text: '',
    selected: null,
    viewportOnly: true,
    overlay: null,
    overlayTime: null,
  };
}

export function stateFromUrl(search = globalThis.location?.search ?? '') {
  const state = defaults();
  const params = new URLSearchParams(search);
  for (const [key, param] of Object.entries(PARAM_MAP)) {
    if (!params.has(param)) continue;
    const raw = params.get(param);
    if (key === 'lat' || key === 'lon' || key === 'zoom') {
      const value = Number(raw);
      if (Number.isFinite(value)) state[key] = value;
    } else if (key === 'from' || key === 'to') {
      const value = Number(raw);
      state[key] = Number.isFinite(value) ? value : null;
    } else if (key === 'viewportOnly') {
      state.viewportOnly = raw !== '0';
    } else {
      state[key] = raw === '' ? null : raw;
    }
  }
  return state;
}

export function urlFromState(state, base = globalThis.location) {
  const params = new URLSearchParams();
  if (state.place) params.set('q', state.place);
  if (Number.isFinite(state.lat)) params.set('lat', Number(state.lat).toFixed(4));
  if (Number.isFinite(state.lon)) params.set('lon', Number(state.lon).toFixed(4));
  if (Number.isFinite(state.zoom)) params.set('z', String(Math.round(state.zoom)));
  if (state.from !== null && state.from !== undefined) params.set('from', String(state.from));
  if (state.to !== null && state.to !== undefined) params.set('to', String(state.to));
  if (state.provider && state.provider !== 'all') params.set('p', state.provider);
  if (state.text) params.set('t', state.text);
  if (state.selected) params.set('sel', state.selected);
  if (state.viewportOnly === false) params.set('vp', '0');
  if (state.overlay) params.set('ov', state.overlay);
  if (state.overlayTime) params.set('ovt', state.overlayTime);
  const query = params.toString();
  const path = base?.pathname ?? '/';
  return `${path}${query ? `?${query}` : ''}`;
}

export function createBus() {
  const listeners = new Map();
  return {
    on(name, fn) {
      if (!listeners.has(name)) listeners.set(name, new Set());
      listeners.get(name).add(fn);
      return () => listeners.get(name)?.delete(fn);
    },
    emit(name, detail) {
      for (const fn of listeners.get(name) ?? []) {
        try {
          fn(detail, name);
        } catch (error) {
          console.error(`[bus] listener for ${name} failed`, error);
        }
      }
      const custom = new CustomEvent(name, { detail, bubbles: false });
      document.dispatchEvent(custom);
    },
  };
}

export function createStore(initial = stateFromUrl()) {
  let state = { ...defaults(), ...initial };
  const subscribers = new Set();
  let syncing = false;

  function notify(changed) {
    for (const fn of subscribers) {
      try {
        fn(state, changed);
      } catch (error) {
        console.error('[store] subscriber failed', error);
      }
    }
  }

  function syncUrl() {
    if (syncing) return;
    const url = urlFromState(state);
    const current = `${globalThis.location.pathname}${globalThis.location.search}`;
    if (url === current) return;
    try {
      globalThis.history.replaceState({ kartenzeit: true }, '', url);
    } catch {
      /* file:// or sandboxed context — state stays in memory */
    }
  }

  return {
    getState: () => state,
    update(patch, { url = true, silent = false } = {}) {
      const changed = [];
      for (const [key, value] of Object.entries(patch ?? {})) {
        if (state[key] !== value) changed.push(key);
        state[key] = value;
      }
      if (!changed.length) return state;
      if (url) syncUrl();
      if (!silent) notify(changed);
      return state;
    },
    replace(next, options) {
      const patch = {};
      for (const key of Object.keys(defaults())) {
        if (state[key] !== next[key]) patch[key] = next[key];
      }
      return this.update(patch, options);
    },
    subscribe(fn) {
      subscribers.add(fn);
      return () => subscribers.delete(fn);
    },
    reset({ keepView = true } = {}) {
      const patch = { ...defaults() };
      if (keepView) {
        patch.lat = state.lat;
        patch.lon = state.lon;
        patch.zoom = state.zoom;
        patch.place = state.place;
      }
      return this.update(patch);
    },
    /** Restore state from a URL (popstate / deep link). */
    fromUrl(search = globalThis.location.search) {
      syncing = true;
      try {
        this.replace(stateFromUrl(search));
      } finally {
        syncing = false;
      }
      return state;
    },
  };
}

export { defaults as defaultState };

/**
 * iiif.js — IIIF helpers for e-rara digitalisates (owner: zurich-maps-3).
 *
 * Verified upstream (2026-10-18): Presentation API 2.0 manifests under
 * https://www.e-rara.ch/i3f/v20/<id>/manifest and Image API 2 (level 2)
 * services under https://www.e-rara.ch/i3f/v20/<imageId>. Both send
 * `access-control-allow-origin: *`.
 */

/** Build an Image API URL. Rejects anything that is not a known IIIF base. */
export function imageUrl(serviceId, { region = 'full', size = '1200,', rotation = 0, quality = 'default', format = 'jpg' } = {}) {
  if (!serviceId) return null;
  const base = String(serviceId).replace(/\/+$/, '');
  return `${base}/${region}/${size}/${rotation}/${quality}.${format}`;
}

export function thumbnailUrl(serviceId, width = 304) {
  return imageUrl(serviceId, { size: `${width},`, format: 'jpg' });
}

/** `!1200,1200` keeps the aspect ratio inside the box (Image API 2 sizeByConfinedWh). */
export function containUrl(serviceId, box = 1200) {
  return imageUrl(serviceId, { size: `!${box},${box}` });
}

export function manifestUrl(record) {
  return record?.iiifManifest ?? null;
}

/** Presentation API 3 uses `items`; API 2 uses `sequences[].canvases[]`. */
export function canvasesOf(manifest) {
  if (Array.isArray(manifest?.sequences)) return manifest.sequences.flatMap((sequence) => sequence.canvases ?? []);
  if (Array.isArray(manifest?.items)) return manifest.items;
  return [];
}

export function serviceIdOfCanvas(canvas) {
  const image = canvas?.images?.[0] ?? canvas?.items?.[0];
  const resource = image?.resource ?? image?.body ?? null;
  const service = resource?.service?.[0] ?? resource?.service ?? null;
  return service?.['@id'] ?? service?.id ?? null;
}

export function imageSizeOfCanvas(canvas) {
  const image = canvas?.images?.[0] ?? canvas?.items?.[0];
  const resource = image?.resource ?? image?.body ?? null;
  return { width: resource?.width ?? canvas?.width ?? null, height: resource?.height ?? canvas?.height ?? null };
}

export function pageFromCanvas(canvas, index) {
  const { width, height } = imageSizeOfCanvas(canvas);
  return {
    index,
    label: labelOf(canvas) || `[${index + 1}]`,
    serviceId: serviceIdOfCanvas(canvas),
    width,
    height,
  };
}

function labelOf(node) {
  const label = node?.label;
  if (!label) return null;
  if (typeof label === 'string') return label;
  if (Array.isArray(label)) return label.map((entry) => entry?.value ?? entry?.['@value'] ?? '').join(' ');
  return label.value ?? label['@value'] ?? null;
}

export function metadataPairs(manifest) {
  return (manifest?.metadata ?? []).map((entry) => ({
    label: labelOf(entry) ?? 'Angabe',
    value: labelOf({ label: entry.value }) ?? '',
  }));
}

/** Normalised manifest view used by the detail panel. */
export async function loadManifest(url, { fetchImpl } = {}) {
  const doFetch = fetchImpl ?? globalThis.fetch;
  if (!url) throw new Error('kein IIIF-Manifest hinterlegt');
  const res = await doFetch(url, { headers: { accept: 'application/json' } });
  if (!res.ok) throw new Error(`IIIF-Manifest nicht erreichbar (HTTP ${res.status})`);
  const manifest = await res.json();
  const pages = canvasesOf(manifest).map(pageFromCanvas).filter((page) => page.serviceId);
  return {
    url,
    label: labelOf(manifest) ?? '',
    attribution: manifest.attribution ?? '',
    license: typeof manifest.license === 'string' ? manifest.license : manifest.license?.['@id'] ?? null,
    metadata: metadataPairs(manifest),
    pages,
    raw: manifest,
  };
}

/** Viewer link on the holding platform: e-rara serves a zoom view per canvas. */
export function upstreamViewerUrl(record, page = null) {
  if (!record?.recordUrl) return null;
  if (!page?.serviceId) return record.recordUrl;
  const id = String(page.serviceId).split('/').filter(Boolean).pop();
  if (!/^\d+$/.test(id ?? '')) return record.recordUrl;
  const base = record.recordUrl.replace(/\/?(doi|content)\/.*$/, '');
  return `${base}/content/zoom/${id}`;
}

/**
 * map.js — Leaflet map, result markers, georeferenced overlays (owner: zurich-maps-2).
 *
 * Real services only (verified 2026-10-18, CORS `*`):
 *   base   https://wmts.geo.admin.ch/1.0.0/ch.swisstopo.pixelkarte-grau/default/current/3857/{z}/{x}/{y}.jpeg
 *   colour https://wmts.geo.admin.ch/1.0.0/ch.swisstopo.pixelkarte-farbe-pk100.noscale/default/current/3857/{z}/{x}/{y}.jpeg
 *   overlay https://wmts.geo.admin.ch/1.0.0/ch.swisstopo.zeitreihen/default/{YYYYMMDD}/3857/{z}/{x}/{y}.png
 */

import { boundsIntersect, isBounds, isPoint } from './records.js';
import { el, setStatus } from './dom.js';

export const BASE_LAYERS = [
  {
    id: 'pixelkarte-grau',
    label: 'swisstopo grau',
    url: 'https://wmts.geo.admin.ch/1.0.0/ch.swisstopo.pixelkarte-grau/default/current/3857/{z}/{x}/{y}.jpeg',
    attribution: '&copy; swisstopo',
    maxZoom: 18,
  },
  {
    id: 'pixelkarte-farbe',
    label: 'swisstopo farbig',
    url: 'https://wmts.geo.admin.ch/1.0.0/ch.swisstopo.pixelkarte-farbe-pk100.noscale/default/current/3857/{z}/{x}/{y}.jpeg',
    attribution: '&copy; swisstopo',
    maxZoom: 18,
  },
  {
    id: 'swissimage',
    label: 'SWISSIMAGE Luftbild',
    url: 'https://wmts.geo.admin.ch/1.0.0/ch.swisstopo.swissimage/default/current/3857/{z}/{x}/{y}.jpeg',
    attribution: '&copy; swisstopo',
    maxZoom: 19,
  },
];

export function init(ctx) {
  const { store, bus } = ctx;
  const container = document.getElementById('map');
  if (!container) return null;
  if (typeof L === 'undefined') {
    setStatus(document.getElementById('map-status'), 'Kartenbibliothek konnte nicht geladen werden.');
    return null;
  }

  const state = store.getState();
  const map = L.map(container, {
    center: [state.lat, state.lon],
    zoom: state.zoom,
    zoomControl: true,
    keyboard: true,
    worldCopyJump: false,
    minZoom: 4,
    maxZoom: 19,
    zoomAnimation: true,
  });

  const bases = {};
  for (const base of BASE_LAYERS) {
    bases[base.label] = L.tileLayer(base.url, {
      attribution: base.attribution,
      maxZoom: base.maxZoom,
      crossOrigin: true,
    });
  }
  bases[BASE_LAYERS[0].label].addTo(map);

  const resultLayer = L.layerGroup().addTo(map);
  const extentLayer = L.layerGroup().addTo(map);
  let overlayLayer = null;
  let overlayDescriptor = null;
  let overlayTime = null;
  let markers = new Map();
  let ignoreMove = false;

  function markerIcon({ selected = false, overlay = false } = {}) {
    const classes = ['kz-marker'];
    if (selected) classes.push('kz-marker--selected');
    if (overlay) classes.push('kz-marker--overlay');
    return L.divIcon({
      className: '',
      html: `<span class="${classes.join(' ')}"><span class="kz-marker__dot"></span></span>`,
      iconSize: [18, 18],
      iconAnchor: [9, 9],
    });
  }

  function pointOf(record) {
    if (isPoint(record.geo)) return [Number(record.geo.lat), Number(record.geo.lon)];
    if (isBounds(record.extent)) {
      return [(record.extent.south + record.extent.north) / 2, (record.extent.west + record.extent.east) / 2];
    }
    return null;
  }

  function tooltipHtml(record) {
    const title = document.createElement('span');
    title.textContent = record.title.length > 120 ? `${record.title.slice(0, 117)}…` : record.title;
    const year = document.createElement('span');
    year.style.display = 'block';
    year.style.color = '#666';
    year.textContent = [record.institution, record.yearStart].filter(Boolean).join(' · ');
    const wrap = document.createElement('div');
    wrap.append(title, year);
    return wrap;
  }

  /** Render markers for the current result set; keep the selected one distinct. */
  function setRecords(records, { selected = null } = {}) {
    resultLayer.clearLayers();
    markers = new Map();
    for (const record of records) {
      const latlng = pointOf(record);
      if (!latlng) continue;
      const isSelected = selected === record.id;
      const marker = L.marker(latlng, {
        icon: markerIcon({ selected: isSelected, overlay: !!record.overlay }),
        keyboard: false,
        title: record.title,
        alt: `${record.title} (${record.institution})`,
      });
      marker.bindTooltip(tooltipHtml(record), { className: 'kz-tooltip', direction: 'top', offset: [0, -8] });
      marker.on('click', () => {
        store.update({ selected: record.id });
        bus.emit('record:selected', { record, from: 'map' });
      });
      marker.addTo(resultLayer);
      markers.set(record.id, marker);
    }
  }

  function showExtent(record) {
    extentLayer.clearLayers();
    if (!isBounds(record?.extent)) return;
    const bounds = [
      [record.extent.south, record.extent.west],
      [record.extent.north, record.extent.east],
    ];
    L.rectangle(bounds, {
      color: '#b01657',
      weight: 2,
      fillColor: '#b01657',
      fillOpacity: 0.12,
      interactive: false,
    }).addTo(extentLayer);
  }

  function selectRecord(record, { pan = true } = {}) {
    for (const [id, marker] of markers) {
      marker.setIcon(markerIcon({ selected: id === record?.id, overlay: false }));
    }
    showExtent(record ?? null);
    if (!record || !pan) return;
    const latlng = pointOf(record);
    if (!latlng) return;
    ignoreMove = true;
    map.panTo(latlng, { animate: false });
    setTimeout(() => {
      ignoreMove = false;
    }, 0);
  }

  function visibleBounds() {
    const b = map.getBounds();
    return { west: b.getWest(), south: b.getSouth(), east: b.getEast(), north: b.getNorth() };
  }

  function fitRecords(records) {
    const points = records.map(pointOf).filter(Boolean);
    if (!points.length) return false;
    if (points.length === 1) {
      map.setView(points[0], Math.max(map.getZoom(), 12), { animate: false });
      return true;
    }
    const bounds = L.latLngBounds(points);
    for (const record of records) {
      if (isBounds(record.extent)) {
        bounds.extend([record.extent.south, record.extent.west]);
        bounds.extend([record.extent.north, record.extent.east]);
      }
    }
    map.fitBounds(bounds, { padding: [28, 28], animate: false, maxZoom: 13 });
    return true;
  }

  /** Time-travel overlay from the swisstopo WMTS `Time` dimension. */
  function setOverlay(descriptor, time = null) {
    overlayDescriptor = descriptor ?? null;
    overlayTime = time ?? descriptor?.timeValues?.[0] ?? null;
    if (overlayLayer) {
      map.removeLayer(overlayLayer);
      overlayLayer = null;
    }
    if (!descriptor) return;
    const template = String(descriptor.urlTemplate).replace('{Time}', overlayTime);
    overlayLayer = L.tileLayer(template, {
      attribution: descriptor.attribution ?? '&copy; swisstopo',
      maxZoom: Math.min(descriptor.maxZoom ?? 18, 18),
      opacity: 0.7,
      crossOrigin: true,
      className: 'kz-overlay-tiles',
    }).addTo(map);
  }

  function setOverlayTime(time) {
    if (!overlayDescriptor) return;
    setOverlay(overlayDescriptor, time);
  }

  function setOverlayOpacity(value) {
    overlayLayer?.setOpacity(value);
  }

  map.on('moveend zoomend', () => {
    if (ignoreMove) return;
    const center = map.getCenter();
    store.update({ lat: center.lat, lon: center.lng, zoom: map.getZoom() }, { silent: true });
    bus.emit('map:moved', { bounds: visibleBounds(), center: { lat: center.lat, lon: center.lng }, zoom: map.getZoom() });
  });

  const layersControl = L.control.layers(bases, null, { position: 'topright', collapsed: true }).addTo(map);
  layersControl.getContainer().setAttribute('aria-label', 'Basiskarte wählen');

  // `#map` is focusable and announced; arrow keys/± work through Leaflet.
  container.addEventListener('keydown', (event) => {
    if (event.key === '+') map.zoomIn();
    else if (event.key === '-') map.zoomOut();
  });

  // Leaflet needs a size refresh when the container becomes visible/resized.
  const resizeObserver = new ResizeObserver(() => map.invalidateSize({ animate: false }));
  resizeObserver.observe(container);

  return {
    map,
    setRecords,
    selectRecord,
    fitRecords,
    visibleBounds,
    setOverlay,
    setOverlayTime,
    setOverlayOpacity,
    getOverlay: () => ({ descriptor: overlayDescriptor, time: overlayTime }),
    markerCount: () => markers.size,
    boundsIntersect,
    invalidate: () => map.invalidateSize({ animate: false }),
    destroy() {
      resizeObserver.disconnect();
      map.remove();
    },
  };
}

/**
 * search.js — place search on the swisstopo search service (owner: zurich-maps-2).
 *
 * Primary endpoint (browser, CORS verified 2026-10-18):
 *   https://api3.geo.admin.ch/rest/services/api/SearchServer?searchText=…&type=locations&sr=4326&limit=n
 * Fallback (our own Worker, for strict networks):
 *   /api/search/places?q=…
 */

import { debounce, el, setHidden, setStatus } from './dom.js';

const UPSTREAM = 'https://api3.geo.admin.ch/rest/services/api/SearchServer';
const PROXY = '/api/search/places';

/** `attrs.label` contains <b> markup; strip it for text, keep the rest verbatim. */
function plain(text) {
  return String(text ?? '').replace(/<[^>]+>/g, '').replace(/\s+/g, ' ').trim();
}

export function parseSearchResults(payload) {
  const results = Array.isArray(payload?.results) ? payload.results : [];
  return results
    .map((entry) => entry?.attrs ?? {})
    .filter((attrs) => Number.isFinite(Number(attrs.lat)) && Number.isFinite(Number(attrs.lon)))
    .map((attrs) => ({
      label: plain(attrs.label) || plain(attrs.detail),
      detail: plain(attrs.detail),
      origin: attrs.origin ?? '',
      lat: Number(attrs.lat),
      lon: Number(attrs.lon),
      zoom: attrs.origin === 'gg25' ? 12 : 14,
      box: attrs.geom_st_box2d ?? null,
    }));
}

export async function searchPlaces(query, { limit = 8, fetchImpl, signal } = {}) {
  const doFetch = fetchImpl ?? globalThis.fetch;
  const trimmed = String(query ?? '').trim();
  if (trimmed.length < 2) return [];
  const params = new URLSearchParams({
    searchText: trimmed,
    type: 'locations',
    sr: '4326',
    limit: String(Math.max(1, Math.min(20, limit))),
  });
  try {
    const res = await doFetch(`${UPSTREAM}?${params}`, { signal, headers: { accept: 'application/json' } });
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    const results = parseSearchResults(await res.json());
    if (results.length) return results;
  } catch (error) {
    // fall through to our Worker proxy
  }
  const res = await doFetch(`${PROXY}?q=${encodeURIComponent(trimmed)}&limit=${limit}`, {
    signal,
    headers: { accept: 'application/json' },
  });
  if (!res.ok) throw new Error(`Ortssuche nicht erreichbar (HTTP ${res.status})`);
  return parseSearchResults(await res.json());
}

export function init(ctx) {
  const { store, bus, api } = ctx;
  const form = document.getElementById('place-form');
  const input = document.getElementById('place-search');
  const list = document.getElementById('place-suggestions');
  const status = document.getElementById('search-status');
  if (!form || !input || !list) return null;

  let options = [];
  let activeIndex = -1;
  let controller = null;

  function closeList() {
    list.hidden = true;
    list.innerHTML = '';
    input.setAttribute('aria-expanded', 'false');
    input.removeAttribute('aria-activedescendant');
    options = [];
    activeIndex = -1;
  }

  function renderOptions(items, { emptyMessage = null } = {}) {
    list.innerHTML = '';
    options = items;
    activeIndex = -1;
    if (emptyMessage) {
      list.append(el('li', { class: 'suggestion--empty' }, emptyMessage));
      list.hidden = false;
      input.setAttribute('aria-expanded', 'true');
      return;
    }
    items.forEach((item, index) => {
      const option = el(
        'li',
        { role: 'option', id: `place-option-${index}`, 'aria-selected': 'false', tabindex: '-1' },
        el('span', { text: item.label }),
        item.detail && item.detail !== item.label ? el('span', { class: 'suggestion__meta', text: item.detail }) : null,
      );
      option.addEventListener('mousedown', (event) => {
        event.preventDefault();
        choose(index);
      });
      option.addEventListener('mouseenter', () => setActive(index));
      list.append(option);
    });
    list.hidden = items.length === 0;
    input.setAttribute('aria-expanded', items.length ? 'true' : 'false');
  }

  function setActive(index) {
    const children = [...list.querySelectorAll('[role="option"]')];
    activeIndex = index;
    children.forEach((child, i) => child.setAttribute('aria-selected', String(i === index)));
    if (children[index]) {
      input.setAttribute('aria-activedescendant', children[index].id);
      children[index].scrollIntoView({ block: 'nearest' });
    }
  }

  function choose(index) {
    const item = options[index];
    if (!item) return;
    store.update({ place: item.label, lat: item.lat, lon: item.lon, zoom: item.zoom });
    bus.emit('place:selected', { place: item, from: 'search' });
    setStatus(status, `Kartenausschnitt: ${item.label}`);
    input.value = item.label;
    closeList();
    input.focus();
  }

  const runSearch = debounce(async (query) => {
    if (controller) controller.abort();
    controller = new AbortController();
    try {
      const results = await searchPlaces(query, { signal: controller.signal, fetchImpl: api?.fetch });
      if (input.value.trim() !== query.trim()) return;
      renderOptions(results, {
        emptyMessage: results.length ? null : `Kein Ort gefunden für «${query.trim()}».`,
      });
      setStatus(status, results.length ? `${results.length} Ortsvorschläge` : '');
    } catch (error) {
      if (error?.name === 'AbortError') return;
      closeList();
      setStatus(status, 'Die Ortssuche ist gerade nicht erreichbar. Die Karte bleibt bedienbar.');
    }
  }, 260);

  input.addEventListener('input', () => {
    const value = input.value;
    store.update({ place: value });
    if (value.trim().length < 2) {
      closeList();
      setStatus(status, '');
      return;
    }
    runSearch(value);
  });

  input.addEventListener('keydown', (event) => {
    const open = !list.hidden && options.length > 0;
    if (event.key === 'ArrowDown' && (open || options.length)) {
      event.preventDefault();
      setActive((activeIndex + 1) % options.length);
    } else if (event.key === 'ArrowUp' && open) {
      event.preventDefault();
      setActive((activeIndex - 1 + options.length) % options.length);
    } else if (event.key === 'Enter') {
      if (open && activeIndex >= 0) {
        event.preventDefault();
        choose(activeIndex);
      } else if (open && options.length) {
        event.preventDefault();
        choose(0);
      }
    } else if (event.key === 'Escape') {
      closeList();
    }
  });

  input.addEventListener('blur', () => setTimeout(closeList, 120));

  form.addEventListener('submit', async (event) => {
    event.preventDefault();
    const query = input.value.trim();
    if (query.length < 2) {
      setStatus(status, 'Bitte mindestens zwei Zeichen eingeben.');
      return;
    }
    setStatus(status, 'Orte werden gesucht …');
    try {
      const results = await searchPlaces(query, { limit: 1, fetchImpl: api?.fetch });
      if (!results.length) {
        setStatus(status, `Kein Ort gefunden für «${query}».`);
        return;
      }
      choose(0);
    } catch {
      setStatus(status, 'Die Ortssuche ist gerade nicht erreichbar. Bitte später erneut versuchen.');
    }
  });

  for (const chip of document.querySelectorAll('.quicklinks .chip[data-place]')) {
    chip.addEventListener('click', async () => {
      const name = chip.dataset.place;
      input.value = name;
      setStatus(status, `${name} wird gesucht …`);
      try {
        const results = await searchPlaces(name, { limit: 1, fetchImpl: api?.fetch });
        if (!results.length) {
          setStatus(status, `Kein Ort gefunden für «${name}».`);
          return;
        }
        choose(0);
      } catch {
        setStatus(status, 'Die Ortssuche ist gerade nicht erreichbar.');
      }
    });
  }

  // Deep link: ?q=Zürich should resolve once on load.
  const initial = store.getState().place;
  if (initial && initial.length >= 2) {
    input.value = initial;
    searchPlaces(initial, { limit: 1, fetchImpl: api?.fetch })
      .then((results) => {
        if (results.length) {
          setStatus(status, `Kartenausschnitt: ${results[0].label}`);
        }
      })
      .catch(() => {});
  }

  document.addEventListener('keydown', (event) => {
    if (event.key === '/' && document.activeElement !== input && !/input|textarea|select/i.test(document.activeElement?.tagName ?? '')) {
      event.preventDefault();
      input.focus();
    }
  });

  return { searchPlaces, closeList, setStatus: (message) => setStatus(status, message) };
}

export { setHidden };

/**
 * results.js — filter panel + result list (owner: zurich-maps-2).
 * The list is the keyboard-accessible twin of the map: every map action has an
 * equivalent here.
 */

import { el, setHidden, setStatus, setText } from './dom.js';
import { formatYear, institutionShort, providerLabel, sortRecords } from './records.js';

const PAGE_SIZE = 30;

export function init(ctx) {
  const { store, bus, index, sources } = ctx;
  const listEl = document.getElementById('results-list');
  const countEl = document.getElementById('results-count');
  const loadingEl = document.getElementById('results-loading');
  const emptyEl = document.getElementById('results-empty');
  const errorEl = document.getElementById('results-error');
  const moreWrap = document.getElementById('results-more');
  const textFilter = document.getElementById('text-filter');
  const fromInput = document.getElementById('year-from');
  const toInput = document.getElementById('year-to');
  const fromLabel = document.getElementById('year-from-label');
  const toLabel = document.getElementById('year-to-label');
  const providerBox = document.getElementById('provider-filters');
  const viewportSwitch = document.getElementById('viewport-filter');
  const resetButton = document.getElementById('reset-filters');

  let visible = [];
  let shown = PAGE_SIZE;
  let currentRecords = [];

  /* ---------------------------------------------------------------- filters */

  function syncRangeInputs() {
    const state = store.getState();
    if (fromInput && state.from !== null) fromInput.value = String(state.from);
    if (toInput && state.to !== null) toInput.value = String(state.to);
    setText(fromLabel, fromInput?.value ?? '');
    setText(toLabel, toInput?.value ?? '');
  }

  function clampYears(which, value) {
    const state = store.getState();
    const min = Number(fromInput?.min ?? 1400);
    const max = Number(fromInput?.max ?? 2100);
    const numeric = Math.max(min, Math.min(max, Number(value)));
    if (which === 'from') {
      store.update({ from: numeric, to: Math.max(numeric, state.to ?? numeric) });
    } else {
      store.update({ to: numeric, from: Math.min(numeric, state.from ?? numeric) });
    }
  }

  fromInput?.addEventListener('input', () => clampYears('from', fromInput.value));
  toInput?.addEventListener('input', () => clampYears('to', toInput.value));

  for (const preset of document.querySelectorAll('.presets .chip[data-preset]')) {
    preset.addEventListener('click', () => {
      const [from, to] = preset.dataset.preset.split('-').map(Number);
      store.update({ from, to });
    });
  }

  function renderProviders() {
    if (!providerBox) return;
    providerBox.innerHTML = '';
    for (const [providerId, count] of index.providerCounts) {
      const id = `provider-${providerId}`;
      const row = el('label', { class: 'check-row', for: id });
      const input = el('input', { type: 'checkbox', id, value: providerId, checked: true });
      input.addEventListener('change', () => {
        const checked = [...providerBox.querySelectorAll('input:checked')].map((node) => node.value);
        const all = [...providerBox.querySelectorAll('input')].map((node) => node.value);
        store.update({ provider: checked.length === all.length ? 'all' : checked.join(',') });
      });
      row.append(
        input,
        el('span', {}, el('strong', { text: providerLabel(providerId, sources) }), el('small', { text: `${count} Einträge` })),
      );
      providerBox.append(row);
    }
  }

  function syncProviderInputs() {
    if (!providerBox) return;
    const state = store.getState();
    const selected = state.provider && state.provider !== 'all' ? new Set(String(state.provider).split(',')) : null;
    for (const input of providerBox.querySelectorAll('input')) {
      input.checked = !selected || selected.has(input.value);
    }
  }

  viewportSwitch?.addEventListener('change', () => store.update({ viewportOnly: viewportSwitch.checked }));
  resetButton?.addEventListener('click', () => store.reset({ keepView: true }));
  document.getElementById('empty-reset')?.addEventListener('click', () => store.reset({ keepView: true }));
  textFilter?.addEventListener('input', () => {
    shown = PAGE_SIZE;
    store.update({ text: textFilter.value });
  });

  /* ------------------------------------------------------------------- list */

  function thumbnail(record) {
    if (!record.thumbnail) {
      const placeholder = el('span', { class: 'result__thumb', 'aria-hidden': 'true' });
      return placeholder;
    }
    const img = el('img', {
      class: 'result__thumb',
      src: record.thumbnail,
      alt: '',
      loading: 'lazy',
      decoding: 'async',
      referrerpolicy: 'no-referrer',
    });
    img.addEventListener('error', () => {
      img.dataset.fallback = 'true';
      img.removeAttribute('src');
    });
    return img;
  }

  function resultRow(record, state) {
    const selected = state.selected === record.id;
    const href = `?sel=${encodeURIComponent(record.id)}`;
    const link = el('a', {
      class: 'result__button',
      href,
      'aria-current': selected ? 'true' : null,
      'data-id': record.id,
      onclick: (event) => {
        event.preventDefault();
        select(record, { source: 'list' });
      },
    });
    const meta = el('span', { class: 'result__meta' },
      el('span', { class: 'result__year', text: formatYear(record) }),
      el('span', { class: 'result__badge', text: record.type === 'atlas' ? 'Atlas' : 'Karte' }),
      record.overlay ? el('span', { class: 'result__badge result__badge--overlay', text: 'Overlay' }) : null,
    );
    const body = el('span', { class: 'result__body' },
      meta,
      el('span', { class: 'result__title', text: record.title }),
      el('span', { class: 'result__inst', text: institutionShort(record) }),
    );
    link.append(thumbnail(record), body);
    return el('li', { class: 'result' }, link);
  }

  function render(records, state) {
    visible = sortRecords(records, 'year-desc');
    shown = Math.min(Math.max(shown, PAGE_SIZE), Math.max(visible.length, PAGE_SIZE));
    const slice = visible.slice(0, shown);
    listEl.innerHTML = '';
    const fragment = document.createDocumentFragment();
    for (const record of slice) fragment.append(resultRow(record, state));
    listEl.append(fragment);

    setText(
      countEl,
      `${visible.length} von ${currentRecords.length} Karten${visible.length === currentRecords.length ? '' : ' (gefiltert)'}`,
    );
    setHidden(emptyEl, visible.length > 0);
    setHidden(listEl, visible.length === 0);
    setHidden(loadingEl, true);

    if (moreWrap) {
      const remaining = visible.length - slice.length;
      if (remaining > 0) {
        moreWrap.hidden = false;
        moreWrap.innerHTML = '';
        moreWrap.append(
          el('button', {
            class: 'btn btn--secondary',
            type: 'button',
            text: `${Math.min(remaining, PAGE_SIZE)} weitere Karten anzeigen (${remaining} offen)`,
            onclick: () => {
              shown += PAGE_SIZE;
              render(visible, store.getState());
            },
          }),
        );
      } else {
        moreWrap.hidden = true;
        moreWrap.innerHTML = '';
      }
    }
  }

  function select(record, { source = 'list' } = {}) {
    store.update({ selected: record.id });
    bus.emit('record:selected', { record, from: source });
  }

  function highlight(selectedId) {
    for (const link of listEl.querySelectorAll('.result__button')) {
      const active = link.dataset.id === selectedId;
      if (active) link.setAttribute('aria-current', 'true');
      else link.removeAttribute('aria-current');
    }
  }

  function setLoading(isLoading) {
    setHidden(loadingEl, !isLoading);
    if (isLoading) setStatus(countEl, 'Karten werden geladen …');
  }

  function showError(message) {
    setHidden(loadingEl, true);
    setHidden(listEl, true);
    if (errorEl) {
      errorEl.hidden = false;
      const text = errorEl.querySelector('span') ?? el('span');
      text.textContent = ` ${message}`;
      errorEl.insertBefore(text, errorEl.querySelector('button'));
    }
    setText(countEl, 'Keine Verbindung zu den Kartendaten');
  }

  function setRecords(records) {
    currentRecords = records;
    setHidden(errorEl, true);
    return records;
  }

  function applyFilters({ bounds = null } = {}) {
    const state = store.getState();
    return ctx.filter(state, currentRecords, { bounds, viewportOnly: state.viewportOnly });
  }

  return {
    render,
    highlight,
    select,
    setLoading,
    showError,
    setRecords,
    applyFilters,
    syncRangeInputs,
    syncProviderInputs,
    renderProviders,
    getFiltered: () => visible,
    resultLinks: () => [...listEl.querySelectorAll('.result__button')],
  };
}

/**
 * detail.js — map detail panel (owner: zurich-maps-3).
 * Shows title, dates, creators, holding institution, rights, a working IIIF
 * viewer built from the record's manifest, and a prominent link to the
 * original collection record.
 */

import { el, setText } from './dom.js';
import { dateRange, formatYear } from './records.js';
import { containUrl, loadManifest, upstreamViewerUrl } from './iiif.js';

export function init(ctx) {
  const { store, bus, api } = ctx;
  const dialog = document.getElementById('detail-dialog');
  const body = document.getElementById('detail-body');
  const kicker = document.getElementById('detail-kicker');
  const closeButton = document.getElementById('detail-close');
  if (!dialog || !body) return null;

  let currentRecord = null;
  let manifest = null;
  let pageIndex = 0;
  let zoomLevel = 1200;
  let loadToken = 0;

  function metaRow(label, value, className = null) {
    if (!value) return null;
    return el('div', {},
      el('dt', { text: label }),
      el('dd', { class: className, text: value }),
    );
  }

  function renderViewer() {
    const viewer = el('div', { class: 'detail__viewer', id: 'detail-iiif' });
    const caption = el('p', { class: 'viewer-caption' });

    if (!currentRecord?.iiifManifest) {
      if (currentRecord?.thumbnail) {
        viewer.append(
          el('img', { src: currentRecord.thumbnail.replace(/full\/\d+\//, 'full/1200,'), alt: `Digitalisat: ${currentRecord.title}` }),
        );
        caption.append(el('span', { text: 'Vorschau aus dem Digitalisat der besitzenden Institution' }));
      } else {
        viewer.append(el('p', { class: 'detail__error', text: 'Für diesen Eintrag ist kein Digitalisat verlinkt.' }));
      }
      return [viewer, caption];
    }

    if (!manifest) {
      viewer.append(el('p', { class: 'viewer-caption', text: 'IIIF-Manifest wird geladen …' }));
      return [viewer, caption];
    }

    const page = manifest.pages[pageIndex] ?? manifest.pages[0];
    if (!page) {
      viewer.append(el('p', { class: 'detail__error', text: 'Das IIIF-Manifest enthält keine Bildseiten.' }));
      return [viewer, caption];
    }
    const img = el('img', {
      src: containUrl(page.serviceId, zoomLevel),
      alt: `Digitalisat (${page.label}) von: ${currentRecord.title}`,
      loading: 'eager',
      referrerpolicy: 'no-referrer',
    });
    img.addEventListener('error', () => {
      viewer.innerHTML = '';
      viewer.append(el('p', { class: 'detail__error', text: 'Das Digitalisat konnte nicht geladen werden. Der Originaleintrag bleibt verlinkt.' }));
    });
    viewer.append(img);

    caption.append(
      el('span', { text: `Seite ${pageIndex + 1} von ${manifest.pages.length}` }),
      el('span', {},
        manifest.pages.length > 1
          ? el('button', {
              class: 'link-button',
              type: 'button',
              text: '‹ vorherige',
              onclick: () => {
                pageIndex = (pageIndex - 1 + manifest.pages.length) % manifest.pages.length;
                render();
              },
            })
          : null,
        manifest.pages.length > 1 ? ' ' : null,
        manifest.pages.length > 1
          ? el('button', {
              class: 'link-button',
              type: 'button',
              text: 'nächste ›',
              onclick: () => {
                pageIndex = (pageIndex + 1) % manifest.pages.length;
                render();
              },
            })
          : null,
        ' ',
        el('button', {
          class: 'link-button',
          type: 'button',
          text: zoomLevel >= 2400 ? 'verkleinern' : 'vergrössern',
          onclick: () => {
            zoomLevel = zoomLevel >= 2400 ? 1200 : 3000;
            render();
          },
        }),
      ),
      el('span', {},
        el('a', {
          href: upstreamViewerUrl(currentRecord, page) ?? currentRecord.recordUrl,
          target: '_blank',
          rel: 'noopener noreferrer',
          text: 'Original-Viewer ↗',
        }),
      ),
    );
    return [viewer, caption];
  }

  function render() {
    if (!currentRecord) return;
    const record = currentRecord;
    const range = dateRange(record);
    body.innerHTML = '';
    setText(kicker, record.type === 'atlas' ? 'Atlas' : record.type === 'overlay' ? 'Georeferenzierte Karte' : 'Karte');

    body.append(
      el('p', { class: 'detail__year' },
        el('span', { text: formatYear(record) }),
        range.basis === 'publication' && record.depictedYearStart
          ? el('span', { text: ' · Kartendatum abweichend' })
          : null,
      ),
      el('h2', { id: 'detail-title', text: record.title }),
      el('p', { class: 'detail__subtitle', text: [record.imprint, record.creators?.join('; ')].filter(Boolean).join(' · ') || record.institution }),
    );

    const [viewer, caption] = renderViewer();
    body.append(viewer, caption);

    const actions = el('div', { class: 'detail__actions' });

    if (record.iiifManifest) {
      actions.append(
        el('a', {
          class: 'btn btn--secondary',
          href: record.iiifManifest,
          target: '_blank',
          rel: 'noopener noreferrer',
        }, el('span', { class: 'btn__text', text: 'IIIF-Manifest öffnen' })),
      );
    }
    if (record.overlay?.urlTemplate) {
      actions.append(
        el('button', {
          class: 'btn btn--primary',
          type: 'button',
          onclick: () => {
            store.update({ overlay: record.overlay.layerId ?? record.id, overlayTime: record.overlay.timeValue ?? null });
            bus.emit('overlay:requested', { record });
          },
        }, el('span', { class: 'btn__text', text: 'Overlay auf der Karte einblenden' })),
      );
    }
    body.append(actions);

    const meta = el('dl', { class: 'meta-list' },
      metaRow('Institution', record.institution),
      metaRow('Signatur', record.shelfmark),
      metaRow('Urheber', record.creators?.length ? record.creators.join('; ') : null),
      metaRow('Verlag', record.publisher),
      metaRow('Impressum', record.imprint),
      metaRow('Kartendatum', record.depictedYearStart ? `${record.depictedYearStart}${record.depictedYearEnd && record.depictedYearEnd !== record.depictedYearStart ? `–${record.depictedYearEnd}` : ''}` : null),
      metaRow('Ausgabejahr (Publikation)', record.yearStart ? `${record.yearStart}${record.yearEnd && record.yearEnd !== record.yearStart ? `–${record.yearEnd}` : ''}` : null),
      metaRow('Rechte', record.rights, 'rights'),
      metaRow('Quelle', record.providerId),
      metaRow('Kennung', record.id),
    );
    body.append(meta);

    const source = el('div', { class: 'detail__source' });
    source.append(
      el('p', { text: `Der Eintrag liegt im Originalbestand von ${record.institution}. Dort finden Sie Katalogdaten, Rechte und das vollständige Digitalisat.` }),
      el('a', {
        class: 'btn btn--primary btn--block',
        href: record.recordUrl,
        target: '_blank',
        rel: 'noopener noreferrer',
      }, el('span', { class: 'btn__text', text: 'Zum Originaleintrag ↗' })),
    );
    body.append(source);

    body.append(
      el('p', { class: 'detail__note' },
        range.basis === 'depicted'
          ? 'Das angezeigte Datum ist das im Datensatz genannte Kartendatum. '
          : 'Das angezeigte Datum ist das Publikationsjahr des Digitalisats aus dem Katalogdatensatz. ',
        'Metadaten und Bilder stammen unverändert von der besitzenden Institution; diese Anwendung kopiert keine Karten.',
      ),
    );
  }

  async function loadFor(record) {
    const token = ++loadToken;
    manifest = null;
    pageIndex = 0;
    zoomLevel = 1200;
    if (!record?.iiifManifest) return;
    try {
      const loaded = await loadManifest(record.iiifManifest, { fetchImpl: api?.fetch });
      if (token !== loadToken) return;
      manifest = loaded;
      render();
    } catch (error) {
      if (token !== loadToken) return;
      manifest = { pages: [], error: error.message };
      render();
    }
  }

  function open(record) {
    currentRecord = record;
    render();
    if (typeof dialog.showModal === 'function') {
      if (!dialog.open) dialog.showModal();
    } else {
      dialog.setAttribute('open', '');
    }
    document.body.classList.add('detail-open');
    loadFor(record);
  }

  function close({ clearSelection = true } = {}) {
    currentRecord = null;
    manifest = null;
    loadToken += 1;
    document.body.classList.remove('detail-open');
    if (dialog.open && typeof dialog.close === 'function') dialog.close();
    else dialog.removeAttribute('open');
    if (clearSelection) store.update({ selected: null });
  }

  closeButton?.addEventListener('click', () => close());
  dialog.addEventListener('close', () => {
    document.body.classList.remove('detail-open');
    if (store.getState().selected) store.update({ selected: null });
  });
  dialog.addEventListener('click', (event) => {
    if (event.target === dialog) close();
  });

  return {
    open,
    close,
    render,
    getRecord: () => currentRecord,
  };
}

/**
 * main.js — bootstrap and wiring (owner: zurich-maps-1).
 *
 * Modules are optional: each one is imported dynamically and a failure only
 * disables that part of the UI (coordination decision D4), so the shell always
 * stays usable and every record keeps a link to its original collection.
 */

import { createBus, createStore } from './store.js';
import { el, setHidden, setStatus, setText } from './dom.js';
import {
  buildIndex,
  filterRecords,
  loadDataset,
  loadSources,
  toRecordList,
  YEAR_MIN,
  yearDomain,
  yearLabel,
  OVERLAYS_URL,
} from './records.js';

const state = createStore();
const bus = createBus();
const api = { fetch: (...args) => globalThis.fetch(...args) };

async function safeInit(name, loader, ctx) {
  try {
    const module = await loader();
    if (typeof module?.init !== 'function') return null;
    const instance = module.init(ctx);
    return instance ?? { ok: true };
  } catch (error) {
    console.error(`[kartenzeit] module "${name}" failed to initialise`, error);
    return null;
  }
}

function setFacts(index) {
  setText(document.getElementById('fact-records'), index.total ? String(index.total) : '–');
  setText(
    document.getElementById('fact-years'),
    index.minYear ? `${index.minYear}–${index.maxYear}` : 'nicht angegeben',
  );
}

function configureYearInputs(index) {
  const domain = yearDomain(index);
  const from = document.getElementById('year-from');
  const to = document.getElementById('year-to');
  for (const input of [from, to]) {
    if (!input) continue;
    input.min = String(domain.min);
    input.max = String(domain.max);
    input.step = '5';
  }
  const current = state.getState();
  if (current.from === null || current.to === null) {
    state.update({ from: domain.min, to: domain.max }, { silent: true });
  }
  return domain;
}

function setupOverlayBar(ctx, overlays) {
  const bar = document.getElementById('overlay-bar');
  const toggle = document.getElementById('overlay-toggle');
  const select = document.getElementById('overlay-edition');
  const opacity = document.getElementById('overlay-opacity');
  const opacityValue = document.getElementById('overlay-opacity-value');
  const close = document.getElementById('overlay-close');
  if (!bar || !toggle || !select) return null;

  const map = ctx.map;
  const usable = (overlays?.overlays ?? []).filter((entry) => entry.id === 'ch.swisstopo.zeitreihen');

  function fillEdition(descriptor) {
    select.innerHTML = '';
    for (const value of descriptor.timeValues) {
      const year = /^\d{8}$/.test(value) ? value.slice(0, 4) : value;
      select.append(el('option', { value, text: year }));
    }
  }

  function openBar(descriptor, time) {
    setHidden(bar, false);
    toggle.setAttribute('aria-pressed', 'true');
    fillEdition(descriptor);
    select.value = time ?? descriptor.timeValues[0];
    map?.setOverlay(descriptor, select.value);
    map?.setOverlayOpacity(Number(opacity?.value ?? 70) / 100);
  }

  function closeBar() {
    setHidden(bar, true);
    toggle.setAttribute('aria-pressed', 'false');
    map?.setOverlay(null);
    state.update({ overlay: null, overlayTime: null });
  }

  const zeitreihe = usable[0] ?? overlays?.overlays?.find((entry) => (entry.timeValues ?? []).length > 5) ?? null;
  if (!zeitreihe) {
    toggle.disabled = true;
    toggle.title = 'Für dieses Gebiet ist kein georeferenziertes Zeitreise-Overlay verfügbar.';
  }

  toggle.addEventListener('click', () => {
    if (!zeitreihe) return;
    const pressed = toggle.getAttribute('aria-pressed') === 'true';
    if (pressed) closeBar();
    else {
      openBar(zeitreihe, zeitreihe.timeValues[0]);
      state.update({ overlay: zeitreihe.id, overlayTime: zeitreihe.timeValues[0] });
    }
  });
  close?.addEventListener('click', closeBar);
  select.addEventListener('change', () => {
    map?.setOverlayTime(select.value);
    state.update({ overlayTime: select.value });
  });
  opacity?.addEventListener('input', () => {
    const value = Number(opacity.value);
    setText(opacityValue, `${value} %`);
    map?.setOverlayOpacity(value / 100);
  });

  return { openBar, closeBar, descriptor: zeitreihe };
}

function setupMapToolbar(ctx, index) {
  const home = document.getElementById('map-home');
  const fit = document.getElementById('map-fit');
  home?.addEventListener('click', () => {
    state.update({ lat: 47.3769, lon: 8.5417, zoom: 13 });
    ctx.map?.map?.setView([47.3769, 8.5417], 13, { animate: true });
  });
  fit?.addEventListener('click', () => {
    const records = ctx.results?.getFiltered?.() ?? index.records;
    const ok = ctx.map?.fitRecords(records) ?? false;
    setStatus(document.getElementById('map-status'), ok ? `${records.length} Karten eingepasst` : 'Keine Treffer mit Koordinaten');
  });
}

async function loadOverlayDescriptors() {
  try {
    const res = await fetch(OVERLAYS_URL, { headers: { accept: 'application/json' } });
    if (!res.ok) return null;
    return await res.json();
  } catch {
    return null;
  }
}

async function bootstrap() {
  const results = await safeInit('results', () => import('./results.js'), null);
  const map = await safeInit('map', () => import('./map.js'), null);
  const search = await safeInit('search', () => import('./search.js'), null);
  const detail = await safeInit('detail', () => import('./detail.js'), null);

  const ctxBase = { store: state, bus, dom: await import('./dom.js'), api };

  let dataset = { records: [], generatedAt: null };
  let index = buildIndex([]);
  let sources = null;
  let overlays = null;

  results?.setLoading?.(true);

  try {
    [dataset, sources, overlays] = await Promise.all([
      loadDataset(),
      loadSources().catch(() => null),
      loadOverlayDescriptors(),
    ]);
    index = buildIndex(toRecordList(dataset));
  } catch (error) {
    console.error('[kartenzeit] seed data failed', error);
    results?.showError?.('Die Kartendaten konnten nicht geladen werden.');
    setText(document.getElementById('fact-records'), '–');
  }

  setFacts(index);
  configureYearInputs(index);

  const ctx = {
    ...ctxBase,
    index,
    sources,
    overlays,
    records: index.records,
    filter: filterRecords,
    map,
    results,
    search,
    detail,
  };

  // Modules created before data was available still need the same context.
  for (const module of [results, map, search, detail]) {
    if (module && typeof module.setContext === 'function') module.setContext(ctx);
  }

  if (!index.records.length) {
    results?.setRecords?.([]);
    results?.render?.([], state.getState());
  } else {
    results?.setRecords?.(index.records);
    results?.renderProviders?.();
    results?.syncRangeInputs?.();
  }

  const overlayBar = setupOverlayBar(ctx, overlays);
  setupMapToolbar(ctx, index);

  function applyState({ changed = [] } = {}) {
    const current = state.getState();
    results?.syncRangeInputs?.();
    results?.syncProviderInputs?.();
    const viewport = document.getElementById('viewport-filter');
    if (viewport) viewport.checked = current.viewportOnly;

    const filtered = filterRecords(current, index.records, {
      bounds: map?.visibleBounds?.() ?? null,
      viewportOnly: current.viewportOnly,
    });
    results?.render?.(filtered, current);
    map?.setRecords?.(filtered, { selected: current.selected });

    const selectedRecord = current.selected ? index.byId.get(current.selected) : null;
    if (selectedRecord) {
      map?.selectRecord?.(selectedRecord, { pan: changed.includes('selected') });
      results?.highlight?.(selectedRecord.id);
      if (!detail?.getRecord?.() || detail.getRecord()?.id !== selectedRecord.id) {
        detail?.open?.(selectedRecord);
      }
    } else {
      map?.selectRecord?.(null);
      results?.highlight?.(null);
    }

    setStatus(
      document.getElementById('map-status'),
      index.records.length
        ? `${filtered.length} Karten · Zeitraum ${yearLabel(current)}`
        : 'Keine Daten geladen',
    );
  }

  state.subscribe((current, changed) => applyState({ changed }));
  bus.on('map:moved', () => applyState({ changed: ['map'] }));
  bus.on('place:selected', ({ place }) => {
    map?.map?.setView([place.lat, place.lon], place.zoom ?? 12, { animate: true });
  });
  bus.on('record:selected', ({ record, from }) => {
    if (from === 'map') {
      map?.selectRecord?.(record);
      detail?.open?.(record);
      results?.highlight?.(record.id);
    } else {
      map?.selectRecord?.(record);
      detail?.open?.(record);
    }
  });
  bus.on('overlay:requested', ({ record }) => {
    const descriptor = overlays?.overlays?.find((entry) => entry.id === record.overlay?.layerId);
    if (descriptor && overlayBar) {
      overlayBar.openBar(descriptor, record.overlay?.timeValue ?? null);
      state.update({ overlay: descriptor.id, overlayTime: record.overlay?.timeValue ?? descriptor.timeValues[0] });
    }
  });
  document.getElementById('retry-records')?.addEventListener('click', () => globalThis.location.reload());

  globalThis.addEventListener('popstate', () => {
    state.fromUrl();
    applyState({ changed: ['popstate'] });
  });

  applyState({ changed: ['init'] });

  // Deep link with ?sel= opens the detail panel once, after first paint.
  const deepLink = state.getState().selected;
  if (deepLink && index.byId.has(deepLink)) {
    bus.emit('record:selected', { record: index.byId.get(deepLink), from: 'deeplink' });
  }

  document.documentElement.dataset.app = 'ready';
  return ctx;
}

if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', () => {
    bootstrap().catch((error) => {
      console.error('[kartenzeit] bootstrap failed', error);
      setHidden(document.getElementById('results-loading'), true);
    });
  });
} else {
  bootstrap().catch((error) => console.error('[kartenzeit] bootstrap failed', error));
}

/**
 * Kartenzeit request handler (owner: zurich-maps-0).
 *
 * Cloudflare Workers static assets serve ./public; this handler adds a small,
 * strictly allowlisted API surface for upstreams that need caching or a
 * same-origin fallback. It never proxies arbitrary URLs.
 *
 *   GET /api/health           → service + upstream status
 *   GET /api/search/places    → swisstopo SearchServer (locations), 5 min edge cache
 *   GET /api/layers           → curated georeferenced overlays (from data/overlays.json)
 *   GET /api/records          → seed records (from data/records.json)
 *
 * Upstreams (verified 2026-10-18, documented in docs/SOURCES.md):
 *   https://api3.geo.admin.ch   swisstopo search service
 *   https://wmts.geo.admin.ch   swisstopo WMTS tiles (used directly by the browser)
 */

const VERSION = '1.0.0';
const USER_AGENT = 'Kartenzeit/1.0 (historical map study; +https://github.com/igor-makarov/maps-n-stuff)';
const UPSTREAM_SEARCH = 'https://api3.geo.admin.ch/rest/services/api/SearchServer';
const ALLOWED_HOSTS = new Set(['api3.geo.admin.ch', 'wmts.geo.admin.ch', 'www.e-rara.ch']);
const CACHE_SECONDS = 300;
const UPSTREAM_TIMEOUT_MS = 8000;
const MAX_QUERY_LENGTH = 80;

const json = (body, init = {}) =>
  new Response(JSON.stringify(body), {
    ...init,
    headers: {
      'content-type': 'application/json; charset=utf-8',
      'cache-control': 'no-store',
      ...(init.headers ?? {}),
    },
  });

async function fetchUpstream(url, { request } = {}) {
  const target = new URL(url);
  if (!ALLOWED_HOSTS.has(target.host)) {
    return json({ error: 'upstream_not_allowed', host: target.host }, { status: 400 });
  }
  const cache = typeof caches !== 'undefined' ? caches.default : null;
  const cacheKey = new Request(target.toString(), { headers: { accept: 'application/json' } });
  if (request?.method === 'GET' && cache) {
    try {
      const hit = await cache.match(cacheKey);
      if (hit) return new Response(hit.body, hit);
    } catch {
      /* cache unavailable in this runtime — continue without it */
    }
  }
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), UPSTREAM_TIMEOUT_MS);
  let upstream;
  try {
    upstream = await fetch(target, {
      headers: { accept: 'application/json', 'user-agent': USER_AGENT },
      signal: controller.signal,
      cf: { cacheTtl: CACHE_SECONDS, cacheEverything: true },
    });
  } catch (error) {
    return json({ error: 'upstream_unreachable', detail: String(error?.message ?? error) }, { status: 502 });
  } finally {
    clearTimeout(timer);
  }
  const body = await upstream.text();
  const response = new Response(body, {
    status: upstream.status,
    headers: {
      'content-type': upstream.headers.get('content-type') ?? 'application/json; charset=utf-8',
      'cache-control': `public, max-age=${CACHE_SECONDS}`,
      'access-control-allow-origin': '*',
      'x-kartenzeit-upstream': target.host,
    },
  });
  if (upstream.ok && request?.method === 'GET' && cache) {
    try {
      await cache.put(cacheKey, response.clone());
    } catch {
      /* ignore cache write failures */
    }
  }
  return response;
}

function readQuery(url) {
  const q = (url.searchParams.get('q') ?? '').trim();
  const limit = Math.max(1, Math.min(20, Number(url.searchParams.get('limit') ?? 8) || 8));
  if (q.length < 2 || q.length > MAX_QUERY_LENGTH) return null;
  return { q, limit };
}

async function assetJson(env, request, path) {
  if (!env.ASSETS) return json({ error: 'assets_binding_missing' }, { status: 500 });
  const assetUrl = new URL(path, request.url);
  const res = await env.ASSETS.fetch(new Request(assetUrl.toString(), { headers: { accept: 'application/json' } }));
  if (!res.ok) return json({ error: 'dataset_unavailable', path }, { status: 502 });
  const body = await res.text();
  return new Response(body, {
    headers: {
      'content-type': 'application/json; charset=utf-8',
      'cache-control': `public, max-age=${CACHE_SECONDS}`,
      'access-control-allow-origin': '*',
    },
  });
}

export default {
  async fetch(request, env) {
    const url = new URL(request.url);

    if (!url.pathname.startsWith('/api/')) {
      return env.ASSETS ? env.ASSETS.fetch(request) : new Response('Not found', { status: 404 });
    }

    if (request.method === 'OPTIONS') {
      return new Response(null, {
        status: 204,
        headers: { 'access-control-allow-origin': '*', 'access-control-allow-methods': 'GET, OPTIONS' },
      });
    }
    if (request.method !== 'GET') {
      return json({ error: 'method_not_allowed' }, { status: 405, headers: { allow: 'GET, OPTIONS' } });
    }

    switch (url.pathname) {
      case '/api/health':
        return json({
          ok: true,
          service: 'kartenzeit',
          version: VERSION,
          upstreams: {
            search: UPSTREAM_SEARCH,
            tiles: 'https://wmts.geo.admin.ch/1.0.0/{layerId}/default/{Time}/3857/{z}/{x}/{y}.{ext}',
            iiif: 'https://www.e-rara.ch/i3f/v20/',
          },
          allowlist: [...ALLOWED_HOSTS],
        });

      case '/api/search/places': {
        const query = readQuery(url);
        if (!query) {
          return json({ error: 'invalid_query', detail: `q must be ${2}–${MAX_QUERY_LENGTH} characters` }, { status: 400 });
        }
        const params = new URLSearchParams({
          searchText: query.q,
          type: 'locations',
          sr: '4326',
          limit: String(query.limit),
        });
        return fetchUpstream(`${UPSTREAM_SEARCH}?${params}`, { request });
      }

      case '/api/layers':
        return assetJson(env, request, '/data/overlays.json');

      case '/api/records':
        return assetJson(env, request, '/data/records.json');

      default:
        return json({ error: 'not_found', path: url.pathname }, { status: 404 });
    }
  },
};

