#!/usr/bin/env node
/**
 * verify-records.mjs — static validation of the seed dataset (owner: zurich-maps-0).
 *
 * Runs without network access and without dependencies. Used by `npm run
 * verify:data` and by tests/records.test.mjs.
 *
 *   node scripts/verify-records.mjs            # report + exit code
 *   node scripts/verify-records.mjs --json     # machine readable
 */
import { readFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import { dirname, resolve } from 'node:path';
import { validateRecords } from '../public/app/records.js';

const here = dirname(fileURLToPath(import.meta.url));
const root = resolve(here, '..');

export async function verifyData({ dataDir = resolve(root, 'public/data') } = {}) {
  const [recordsRaw, sourcesRaw] = await Promise.all([
    readFile(resolve(dataDir, 'records.json'), 'utf8'),
    readFile(resolve(dataDir, 'sources.json'), 'utf8'),
  ]);
  const doc = JSON.parse(recordsRaw);
  const sources = JSON.parse(sourcesRaw);
  const report = validateRecords(doc, sources);
  return { report, doc, sources };
}

if (import.meta.url === `file://${process.argv[1]}`) {
  const asJson = process.argv.includes('--json');
  const { report, doc } = await verifyData();
  if (asJson) {
    console.log(JSON.stringify({ ...report, generatedAt: doc.generatedAt ?? null }, null, 2));
  } else {
    console.log(`records.json: ${report.count} records, generated ${doc.generatedAt ?? 'unknown'}`);
    for (const warning of report.warnings) console.log(`warning: ${warning}`);
    for (const error of report.errors) console.log(`error:   ${error}`);
    console.log(report.ok ? 'dataset OK' : 'dataset INVALID');
  }
  process.exit(report.ok ? 0 : 1);
}
